# এসএসসি সাধারণ গণিত অধ্যায় ১৩ (সসীম ধারা): সহজ ৫, মধ্যম ৮, কঠিন ৪ — মোট ১৭টি সৃজনশীল প্রশ্ন (শুধু উত্তর)
# ক (২), খ (৪), গ (৪)। সব উত্তর নিচে কোডে যাচাই করা
import json, os, math
from fractions import Fraction as F
from math import sqrt, isclose
r2, r3 = sqrt(2), sqrt(3)
def ap_t(a,d,n): return a+(n-1)*d
def ap_s(a,d,n): return F(n,2)*(2*a+(n-1)*d)
def gp_t(a,r,n): return a*r**(n-1)
def gp_s(a,r,n): return a*(r**n-1)/(r-1)

# ---------- যাচাই ----------
assert ap_t(5,4,10)==41 and ap_s(5,4,20)==860 and ap_t(5,4,25)==101                                     # স১
assert sum(range(1,51))==1275 and sum(k*k for k in range(1,21))==2870 and sum(k**3 for k in range(1,11))==3025==sum(range(1,11))**2   # স২
assert gp_t(2,3,6)==486 and gp_s(2,3,8)==6560 and gp_t(2,3,7)==1458                                    # স৩
h=F(1,2); assert gp_t(64,h,7)==1 and gp_s(64,h,10)==F(1023,8) and gp_t(64,h,10)==F(1,8)                 # স৪
assert ap_t(3,5,12)==58 and all(ap_s(3,5,n)==F(n*(5*n+1),2) for n in range(1,30)) and ap_s(3,5,10)==255  # স৫
assert ap_t(2,4,5)==18 and ap_t(2,4,12)==46 and ap_t(2,4,25)==98 and ap_s(2,4,30)==1800                  # ম১
S=lambda n:3*n*n+2*n; assert S(1)==5 and S(2)==16 and S(2)-S(1)==11 and all(S(n)==ap_s(5,6,n) for n in range(1,40)) and ap_t(5,6,15)==89 and S(20)==1240   # ম২
assert 5+8+11==24 and 5*8*11==440 and ap_s(5,3,20)==670                                                # ম৩
assert gp_t(3,2,3)==12 and gp_t(3,2,6)==96 and gp_t(3,2,10)==1536 and gp_s(3,2,10)==3069               # ম৪
assert isclose(gp_t(r2,r2,8),16) and isclose(gp_t(r2,r2,11),32*r2) and isclose(gp_s(r2,r2,10),62+31*r2) and f'{62+31*r2:.2f}'=='105.84'   # ম৫
assert ap_t(500,100,12)==1600 and ap_s(500,100,12)==12600 and ap_s(500,100,16)==20000                   # ম৬
assert gp_s(1,3,6)==364 and gp_s(1,3,8)==3280 and F(int(gp_s(1,3,3)),int(gp_s(1,3,6)))==F(1,28)                  # ম৭
assert (2+18)/2==10 and 2*18==36 and gp_s(2,3,6)==728 and gp_s(2,-3,6)==-364 and ap_s(2,8,15)==870 and gp_t(2,3,6)==486 and 870-486==384   # ম৮
for p,q in ((3,7),(5,2),(10,4)):                                                                         # ক১
    d=-1; a=p+q-1; assert ap_t(a,d,p)==q and ap_t(a,d,q)==p and ap_t(a,d,p+q)==0 and ap_s(a,d,p+q)==F((p+q)*(p+q-1),2)
a,d=58,-4; assert ap_s(a,d,12)==ap_s(a,d,18) and ap_s(a,d,30)==0 and ap_t(a,d,15)==2 and ap_t(a,d,16)==-2 and ap_s(a,d,15)==450 and max(ap_s(a,d,n) for n in range(1,40))==450   # ক২
assert isclose(gp_t(r3,r3,5),9*r3) and isclose(gp_s(r3,r3,8),120+40*r3) and f'{120+40*r3:.2f}'=='189.28' and isclose(gp_t(r3,r3,10),243)   # ক৩
assert all(sum(k*(k+1) for k in range(1,n+1))==n*(n+1)*(n+2)//3 for n in range(1,30)) and 20*21*22//3==3080 and sum((2*k-1)**2 for k in range(1,11))==1330   # ক৪

