# ======== দ্বিতীয় দফা: পাঠ্যবইয়ের ৩টি সৃজনশীল (হুবহু) + অনুশীলনী ১৩ এর অংক মিশিয়ে সহজ ৪, মধ্যম ১০, কঠিন ৩ ========
from sympy import symbols as _S, simplify as _sim, sqrt as _sq, Rational as _R, solve as _sol, log as _log, expand as _ex, radsimp as _rs
L_,K_=_S('l k'); a_=L_+K_-L_*K_; d_=L_+K_
assert _sim(a_+(L_-1)*d_-L_**2)==0 and _sim(a_+(K_-1)*d_-K_**2)==0 and _ex(a_+(L_+K_-1)*d_)==_ex(L_**2+L_*K_+K_**2)
assert _sim((L_+K_)/2*(2*a_+(L_+K_-1)*d_)-(L_+K_)/2*(L_**2+K_**2+L_+K_))==0
r_=-_sq(2); A_=1/_sq(2); assert _sim(A_*r_**3+2)==0 and _sim(A_*r_**8-8*_sq(2))==0 and _sim(A_*r_**11+32)==0 and _sim(A_*(1-r_**7)/(1-r_)-(15*_sq(2)-14)/2)==0
ap=lambda a,d,n: a+(n-1)*d; Sap=lambda a,d,n: n*(2*a+(n-1)*d)/_R(2); gp=lambda a,r,n: a*r**(n-1); Sgp=lambda a,r,n: a*(r**n-1)/(r-1)
assert [2*n-4 for n in (1,2,3,4)]==[-2,0,2,4] and ap(-2,2,10)==16 and Sap(-2,2,20)==340 and Sgp(-2,2,8)==-510
# সহজ
assert ap(3,4,20)==79 and Sap(3,4,25)==1275 and ap(3,4,25)==99
assert sum(range(1,31))==465 and sum(i*i for i in range(1,11))==385 and sum(i**3 for i in range(1,9))==sum(range(1,9))**2==1296
assert gp(3,2,8)==384 and Sgp(3,2,10)==3069 and Sgp(3,2,7)==381
assert ap(30,-4,12)==-14 and Sap(30,-4,15)==30 and ap(30,-4,21)==-50
# মধ্যম
assert sum(range(1,11))==55 and sum(2*n-1 for n in range(1,9))==64
assert Sgp(2,2,8)==510 and sum(2*(-1)**i for i in range(2*5+1))==2
assert 23*50==1150 and (50-6)/11==4 and Sap(6,4,20)==880
nn=_S('nn'); assert ap(13,-2,10)==-5 and _sol(Sap(13,-2,nn)+120,nn)==[-6,20] and ap(13,-2,7)==1 and ap(13,-2,8)==-1
Sn=lambda n:n*(n+2); assert Sn(1)==3 and all(Sn(n)-Sn(n-1)==2*n+1 for n in range(2,30)) and Sn(15)==255 and 2*20+1==41
assert (lambda r,a:(r,a))(-2,3) and 3*(-2)**2==12 and 3*(-2)**5==-96 and gp(3,-2,10)==-1536 and Sgp(3,-2,8)==-255
assert 4*27==108 and Sgp(4,3,6)==1456
t=-_sq(3); B=1/_sq(3); assert _sim(B*t-(-1))==0 and _sim(B*t**5+9)==0 and _sim(B*t**6-9*_sq(3))==0
assert _sol(nn*(nn+1)/2-28,nn)==[-8,7] and sum(i*i for i in range(1,8))==140 and _sol(nn*(nn+1)/2-136,nn)==[-17,16]
assert 2**5==32 and f'{2000/63:.2f}'=='31.75' and f'{32*2000/63:.2f}'=='1015.87'
